package com.shoply.infrastructure.persistence.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Entity @Table(name="orders") public class OrderEntity {@Id private UUID id;@Column(name="user_id",nullable=false)private UUID userId;@Column(nullable=false)private String status;@Column(nullable=false)private BigDecimal subtotal;@Column(name="created_at",insertable=false,updatable=false)private Instant createdAt;@OneToMany(mappedBy="order",cascade=CascadeType.ALL,fetch=FetchType.EAGER)private List<OrderItemEntity> items=new ArrayList<>();protected OrderEntity(){}public OrderEntity(UUID id,UUID userId,String status,BigDecimal subtotal){this.id=id;this.userId=userId;this.status=status;this.subtotal=subtotal;}public UUID getId(){return id;}public UUID getUserId(){return userId;}public String getStatus(){return status;}public void setStatus(String status){this.status=status;}public BigDecimal getSubtotal(){return subtotal;}public List<OrderItemEntity> getItems(){return items;}}
